"""Execution-grounded text-to-SQL harness.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str     policy call (capped: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements
  env.execute(sql, max_rows=20) -> dict          read-only run
  env.descriptions(db_id) -> str                 column descriptions or ""
  env.prompt(name) -> str                        text of a harness file
  env.config -> dict                             parsed config.json

Flow: draft -> execute -> (only if error / empty result) probe the data and ask
for one repair. A non-empty successful draft is kept untouched.
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
STRING_LIT = re.compile(r"'([^']*)'")
IDENT = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")
FK = re.compile(
    r"foreign\s+key\s*\(\s*[\"'`\[]?(\w+)[\"'`\]]?\s*\)\s*references\s+[\"'`\[]?(\w+)",
    re.I,
)
TABLE = re.compile(r"create\s+table\s+(?:if\s+not\s+exists\s+)?[\"'`\[]?(\w+)", re.I)

SQL_START = re.compile(
    r"^\s*(with|select|insert|update|delete|replace|pragma|explain)\b", re.I
)


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    # unclosed fence
    if "```" in text:
        tail = text.split("```")[-1]
        tail = re.sub(r"^\s*(sql|sqlite)\s*", "", tail, flags=re.I)
        if SQL_START.match(tail):
            return tail.strip().rstrip(";").strip()
    lines = [ln for ln in text.splitlines()]
    start = None
    for i, ln in enumerate(lines):
        if SQL_START.match(ln):
            start = i
            break
    if start is not None:
        return "\n".join(lines[start:]).strip().rstrip(";").strip()
    return text.strip().rstrip(";").strip()


def _safe_execute(env, sql, max_rows=20):
    try:
        res = env.execute(sql, max_rows=max_rows)
    except Exception as exc:  # harness/db guard
        return {"ok": False, "error": str(exc), "rows": [], "columns": [], "n_rows": 0}
    if not isinstance(res, dict):
        return {"ok": False, "error": "no result", "rows": [], "columns": [], "n_rows": 0}
    return res


def _tables(schema):
    return TABLE.findall(schema or "")


def _tokens(sql, question):
    """Content tokens from quoted literals, else from the question."""
    toks = []
    for lit in STRING_LIT.findall(sql or ""):
        for t in re.split(r"[^A-Za-z0-9]+", lit):
            if len(t) >= 3:
                toks.append(t)
    if not toks:
        stop = {
            "the", "and", "for", "what", "which", "who", "show", "list", "find",
            "are", "all", "with", "that", "have", "has", "does", "how", "many",
            "give", "their", "them", "from", "was", "were", "any", "each",
        }
        for t in re.split(r"[^A-Za-z0-9]+", question or ""):
            if len(t) >= 4 and t.lower() not in stop:
                toks.append(t)
    seen, out = set(), []
    for t in toks:
        k = t.lower()
        if k not in seen:
            seen.add(k)
            out.append(t)
    return out[:4]


def _probe(env, db_id, sql, question, schema):
    """Cheap read-only diagnostics: real literals, filter-column values, join keys."""
    lines = []
    tabs = _tables(schema)
    used = [t for t in tabs if re.search(r"\b" + re.escape(t) + r"\b", sql or "", re.I)]
    toks = _tokens(sql, question)

    # 1) where do the questioned literals actually occur?
    for t in toks[:3]:
        for tab in used[:4]:
            q = (
                "SELECT * FROM \"%s\" WHERE CAST(\"%s\" AS TEXT) LIKE '%%%s%%' LIMIT 3"
            )
            cols = _columns_of(schema, tab)
            for c in cols:
                if not _textish(schema, tab, c):
                    continue
                res = _safe_execute(env, q % (tab, c, t.replace("'", "''")), max_rows=3)
                if res.get("ok") and res.get("rows"):
                    lines.append(
                        "Literal probe: table %s column %s contains values matching '%s': %s"
                        % (tab, c, t, _fmt(res["rows"][:3]))
                    )
                    break
            if lines and lines[-1].startswith("Literal probe"):
                break

    # 2) sample values of columns used in comparisons (codes vs descriptions)
    for tab, col in _compared_columns(sql, schema)[:4]:
        res = _safe_execute(
            env,
            'SELECT DISTINCT "%s" FROM "%s" LIMIT 12' % (col, tab),
            max_rows=12,
        )
        if res.get("ok") and res.get("rows"):
            lines.append(
                "Values of %s.%s: %s" % (tab, col, _fmt([r[0] for r in res["rows"]]))
            )

    # 3) declared join keys for the tables in play
    fks = [
        "%s.%s -> %s" % (a, b, c)
        for a, b, c in FK.findall(schema or "")
        if a in used or c in used
    ]
    if fks:
        lines.append("Declared foreign keys: " + "; ".join(fks[:10]))
    return "\n".join(lines[:10])


def _create_block(schema, tab):
    m = re.search(
        r"create\s+table\s+(?:if\s+not\s+exists\s+)?[\"'`\[]?" + re.escape(tab) + r"\b.*?;",
        schema or "",
        re.I | re.S,
    )
    return m.group(0) if m else ""


def _columns_of(schema, tab):
    block = _create_block(schema, tab)
    cols = []
    for ln in block.splitlines()[1:]:
        m = re.match(r"\s*[\"'`\[]?(\w+)[\"'`\]]?\s+\w", ln)
        if m and m.group(1).lower() not in (
            "primary", "foreign", "unique", "check", "constraint",
        ):
            cols.append(m.group(1))
    return cols


def _textish(schema, tab, col):
    block = _create_block(schema, tab)
    m = re.search(
        r"[\"'`\[]?" + re.escape(col) + r"[\"'`\]]?\s+([A-Za-z]+)", block, re.I
    )
    if not m:
        return True
    return m.group(1).upper() in ("TEXT", "VARCHAR", "CHAR", "CLOB", "NVARCHAR")


def _compared_columns(sql, schema):
    out = []
    for m in re.finditer(
        r"(?:(\w+)\.)?[\"'`\[]?(\w+)[\"'`\]]?\s*(?:=|LIKE|IN)\s*", sql or "", re.I
    ):
        alias, col = m.group(1), m.group(2)
        tab = None
        if alias:
            am = re.search(
                r"\b(\w+)\s+(?:AS\s+)?" + re.escape(alias) + r"\b", sql, re.I
            )
            tab = am.group(1) if am else alias
        else:
            for t in _tables(schema):
                if col in _columns_of(schema, t):
                    tab = t
                    break
        if tab and _textish(schema, tab, col) and (tab, col) not in out:
            out.append((tab, col))
    return out


def _fmt(rows):
    try:
        return repr(rows)
    except Exception:
        return str(rows)


def solve(task, env):
    cfg = env.config or {}
    budget = getattr(env, "max_calls", 2) or 2
    max_tokens = cfg.get("max_tokens", 800)
    db_id = task["db_id"]
    schema = env.schema(db_id)
    desc = ""
    try:
        desc = env.descriptions(db_id) or ""
    except Exception:
        desc = ""

    user = "Database: %s\n\nSchema:\n%s\n" % (db_id, schema)
    if desc.strip():
        user += "\nColumn descriptions:\n%s\n" % desc.strip()
    user += "\nQuestion: %s" % task["question"]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]
    user += "\n\nWrite the query now."

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    res = _safe_execute(env, sql)
    ok = bool(res.get("ok"))
    nrows = res.get("n_rows")
    if nrows is None:
        nrows = len(res.get("rows") or [])
    needs_repair = (not ok) or nrows == 0
    if not needs_repair or budget < 2:
        return {"sql": sql}

    feedback = "Previous query:\n```sql\n%s\n```\n" % sql
    if not ok:
        feedback += "Execution ERROR: %s\n" % res.get("error")
    else:
        feedback += "Execution succeeded but returned 0 rows.\n"
    probes = ""
    try:
        probes = _probe(env, db_id, sql, task["question"], schema)
    except Exception:
        probes = ""
    if probes:
        feedback += "\nData probes (actual stored values):\n%s\n" % probes
    feedback += (
        "\nOriginal question: %s\n" % task["question"]
    )
    if task.get("hint"):
        feedback += "Hint: %s\n" % task["hint"]
    feedback += "\nSchema:\n%s\n" % schema

    messages2 = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
        {"role": "assistant", "content": "```sql\n%s\n```" % sql},
        {"role": "user", "content": env.prompt("repair_prompt.md") + "\n\n" + feedback},
    ]
    try:
        reply2 = env.chat(messages2, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = _safe_execute(env, sql2)
    ok2 = bool(res2.get("ok"))
    n2 = res2.get("n_rows")
    if n2 is None:
        n2 = len(res2.get("rows") or [])
    if ok2 and (n2 > 0 or not ok):
        return {"sql": sql2}
    if ok2 and ok and n2 == 0:
        return {"sql": sql2}
    return {"sql": sql}

